<?php
session_start(); require_once __DIR__.'/../db.php';
if (empty($_SESSION['user_id']) || ($_SESSION['role']??'')!=='admin') { header('Location: ../login.php'); exit; }
$id=(int)($_GET['id']??$_POST['id']??0); $msg=''; $err=''; if(empty($_SESSION['csrf_token']))$_SESSION['csrf_token']=bin2hex(random_bytes(32));
if ($id<1) die('Invalid staff account.');
if ($_SERVER['REQUEST_METHOD']==='POST') {
 if(!hash_equals($_SESSION['csrf_token'],$_POST['csrf_token']??'')) $err='Security check failed. Refresh and try again.';
 $name=trim($_POST['full_name']??''); $username=trim($_POST['username']??''); $email=trim($_POST['email']??''); $role=$_POST['role']??''; $active=isset($_POST['is_active'])?1:0; $password=$_POST['new_password']??'';
 if(!$err && ($name===''||$username===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||!in_array($role,['storekeeper'],true))) $err='Please complete all fields correctly.';
 if(!$err){$c=$conn->prepare('SELECT id FROM users WHERE (username=? OR email=?) AND id<>?');$c->bind_param('ssi',$username,$email,$id);$c->execute();if($c->get_result()->num_rows)$err='Username or email already belongs to another account.';$c->close();}
 if(!$err && $password!=='' && strlen($password)<8)$err='New password must be at least 8 characters.';
 if(!$err){if($password!==''){$hash=password_hash($password,PASSWORD_DEFAULT);$s=$conn->prepare("UPDATE users SET full_name=?,username=?,email=?,role=?,password=?,is_active=? WHERE id=? AND role='storekeeper'");$s->bind_param('sssssii',$name,$username,$email,$role,$hash,$active,$id);}else{$s=$conn->prepare("UPDATE users SET full_name=?,username=?,email=?,role=?,is_active=? WHERE id=? AND role='storekeeper'");$s->bind_param('ssssii',$name,$username,$email,$role,$active,$id);}if($s->execute()&&$s->affected_rows>=0)$msg='Staff account updated successfully.';else $err='Could not update staff account.';$s->close();}
}
$s=$conn->prepare("SELECT id,full_name,username,email,role,is_active FROM users WHERE id=? AND role='storekeeper'");$s->bind_param('i',$id);$s->execute();$staff=$s->get_result()->fetch_assoc();$s->close();if(!$staff)die('Staff account not found.');
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit Staff - FreshMart</title><link rel="stylesheet" href="../assets/css/modern.css"></head><body><main class="page"><header class="topbar"><div><a class="brand" href="dashboard.php">Fresh<span>Mart</span></a><h1>Edit staff account</h1><p class="muted">Admin can update staff details, role, and reset password.</p></div><a class="btn" href="staff.php">Back to Staff</a></header><section class="panel"><?php if($msg):?><div class="alert success"><?=htmlspecialchars($msg)?></div><?php endif;?><?php if($err):?><div class="alert error"><?=htmlspecialchars($err)?></div><?php endif;?><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($_SESSION['csrf_token'])?>"><input type="hidden" name="id" value="<?=$id?>"><div><label>Full name</label><input name="full_name" value="<?=htmlspecialchars($staff['full_name'])?>" required></div><div><label>Username</label><input name="username" value="<?=htmlspecialchars($staff['username'])?>" required></div><div><label>Email</label><input type="email" name="email" value="<?=htmlspecialchars($staff['email'])?>" required></div><div><label>Role</label><select name="role"><option value="storekeeper" selected>Storekeeper</option></select></div><div><label><input type="checkbox" name="is_active" value="1" style="width:auto" <?=$staff['is_active']?'checked':''?>> Account active</label></div><div><label>New password (optional)</label><input type="password" name="new_password" minlength="8" placeholder="Leave blank to keep current"></div><div style="align-self:end"><button class="btn primary">Save Changes</button></div></form></section></main></body></html>
